p=Path('temp/model_responses')
print('RECENT:')
if p.exists():
 for f in sorted(p.iterdir(), key=lambda x:x.stat().st_mtime, reverse=True)[:5]:
  if f.is_file(): print(str(f),f.stat().st_mtime, f.read_text(errors='replace')[-10000:])
else: print('No local response directory')

